+    }
+    for value in &stats.bytes_transferred {
+        handles.mooncake_bytes_transferred.observe(*value as f64);
+    }
+    for value in &stats.num_descriptors {
+        handles.mooncake_num_descriptors.observe(*value as f64);
+    }
+    handles
